#!/usr/bin/env python3
"""Generate public, ephemeral native cloud qualification configuration."""
import argparse
import base64
import hashlib
import ipaddress
from pathlib import Path
import re

p = argparse.ArgumentParser(description=__doc__)
p.add_argument('--ip', required=True)
p.add_argument('--cup-public-key', required=True, type=Path)
a = p.parse_args()
ip = str(ipaddress.ip_address(a.ip))
if ':' in ip:
    p.error('This deployment currently requires IPv4')
key = a.cup_public_key.read_bytes()
# ML-DSA-44 SubjectPublicKeyInfo, as generated by OpenSSL 3.5+.
if len(key) != 1334 or not key.startswith(bytes.fromhex('30820532300b06096086480165030403110382052100')):
    p.error('Expected ML-DSA-44 public SPKI DER')
config = Path(__file__).resolve().parents[2] / 'config'
s = (config / 'updater/macos-local-test.gni').read_text()
s = s.replace('Isolated loopback update qualification', 'Isolated ephemeral HTTPS update qualification')
s = s.replace('http://127.0.0.1:18158', 'https://' + ip)
s = re.sub(r'browser_operator_cup_key = "[^"]+"',
           'browser_operator_cup_key = "' + base64.b64encode(key).decode() + '"', s)
out = config / 'updater/macos-cloud-test.generated.gni'
out.write_text(s)
print('Generated public cloud config:', out)
print('CUP public SPKI SHA256:', hashlib.sha256(key).hexdigest())
